let active=null,sequence=0;
const records=new Map();
export function closeCustomSelect(){if(!active)return;active.button.setAttribute('aria-expanded','false');active.popover.remove();active=null;}
function sync(select,record){const option=select.selectedOptions[0],label=option?.label||'Выберите',span=record.button.querySelector('span');if(span.textContent!==label)span.textContent=label;record.button.disabled=select.disabled;record.button.setAttribute('aria-label',select.getAttribute('aria-label')||document.querySelector(`label[for="${select.id}"]`)?.textContent||'Выбрать значение');}
function open(select,record){closeCustomSelect();const popover=document.createElement('div');popover.className='custom-select-popover';popover.id='select-options-'+(++sequence);popover.setAttribute('role','listbox');popover.setAttribute('aria-label',record.button.getAttribute('aria-label'));record.button.setAttribute('aria-controls',popover.id);record.button.setAttribute('aria-expanded','true');
  const searchable=select.options.length>8;let query='';if(searchable){const input=document.createElement('input');input.type='search';input.placeholder='Найти…';input.setAttribute('aria-label','Поиск варианта');popover.append(input);input.addEventListener('input',()=>{query=input.value.toLocaleLowerCase('ru');render();});}
  const list=document.createElement('div');list.className='custom-select-options';popover.append(list);
  const render=()=>{list.replaceChildren();for(const option of select.options){if(option.hidden||!option.label.toLocaleLowerCase('ru').includes(query))continue;const button=document.createElement('button');button.type='button';button.setAttribute('role','option');button.setAttribute('aria-selected',String(option.selected));button.disabled=option.disabled;button.textContent=option.label;button.addEventListener('click',()=>{select.value=option.value;select.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}));sync(select,record);closeCustomSelect();record.button.focus({preventScroll:true});});list.append(button);}if(!list.children.length){const p=document.createElement('p');p.textContent='Нет вариантов';list.append(p);}};
  render();document.body.append(popover);active={button:record.button,popover};const rect=record.button.getBoundingClientRect();popover.style.width=Math.max(180,Math.min(rect.width,innerWidth-24))+'px';popover.style.left=Math.max(12,Math.min(rect.left,innerWidth-popover.offsetWidth-12))+'px';const height=Math.min(320,popover.offsetHeight);popover.style.top=(rect.bottom+height+8>innerHeight?Math.max(12,rect.top-height-6):rect.bottom+6)+'px';
  (popover.querySelector('input')||list.querySelector('[aria-selected=true]')||list.querySelector('button'))?.focus({preventScroll:true});
}
export function refreshCustomSelects(){for(const [select,record]of records){if(!select.isConnected){records.delete(select);continue;}sync(select,record);}}
export function installCustomSelects(){
  const enhance=()=>{document.querySelectorAll('select:not([data-customized])').forEach(select=>{if(select.multiple||select.closest('.editor-toolbar,.tiptap'))return;select.dataset.customized='true';const wrapper=document.createElement('div');wrapper.className='custom-select '+(select.className||'');select.before(wrapper);wrapper.append(select);select.classList.add('custom-select-source');select.tabIndex=-1;select.setAttribute('aria-hidden','true');const button=document.createElement('button');button.type='button';button.className='custom-select-trigger';button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-expanded','false');button.innerHTML='<span></span><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="m6 9 6 6 6-6"/></svg>';wrapper.append(button);const record={button};records.set(select,record);sync(select,record);button.addEventListener('click',()=>active?.button===button?closeCustomSelect():open(select,record));select.addEventListener('change',()=>sync(select,record));select.addEventListener('invalid',event=>{event.preventDefault();button.focus();});});refreshCustomSelects();};
  const observer=new MutationObserver(enhance);observer.observe(document.body,{childList:true,subtree:true});enhance();
  document.addEventListener('pointerdown',event=>{if(active&&!event.target.closest('.custom-select-popover')&&!active.button.contains(event.target))closeCustomSelect();});
  document.addEventListener('keydown',event=>{if(!active){if(['ArrowDown','ArrowUp'].includes(event.key)&&event.target.matches('.custom-select-trigger')){event.preventDefault();event.target.click();}return;}if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();const button=active.button;closeCustomSelect();button.focus();}else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const items=[...active.popover.querySelectorAll('[role=option]:not(:disabled)')],index=items.indexOf(document.activeElement);items[event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowDown'?1:items.length-1))%items.length]?.focus();}else if(event.key==='Tab')closeCustomSelect();},true);
  window.addEventListener('resize',closeCustomSelect);document.addEventListener('scroll',event=>{if(active&&!active.popover.contains(event.target))closeCustomSelect();},true);window.addEventListener('hashchange',closeCustomSelect);
}
